gdc(){return"\u0420\u0430\u0437\u0432\u0438\u0458\u0442\u0435 \u043f\u043e\u0432\u0435\u045c\u0435 \u0438\u0437\u0432\u043e\u0440\u0438 \u043d\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438 \u0441\u043e \u043f\u0440\u043e\u0444\u0435\u0441\u0438\u043e\u043d\u0430\u043b\u0435\u043d \u043f\u0440\u0438\u0441\u0442\u0430\u043f. \u041c\u043e\u0436\u0435 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0430 \u0438\u043b\u0438 \u0446\u0435\u043b\u043e\u0441\u043d\u043e \u0440\u0430\u0431\u043e\u0442\u043d\u043e \u0432\u0440\u0435\u043c\u0435 \u0441\u043e \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u0435\u043d \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0458\u0430\u043b \u0437\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438."},
