gdf(){return"\u0411\u0438\u0437\u043d\u0435\u0441\u0438\u0439\u043d \u043c\u043e\u0434\u0435\u043b\u044d\u044d \u04e9\u0440\u0433\u04e9\u0436\u04af\u04af\u043b"},
gd3(){return"\u0411\u043e\u0433\u0438\u043d\u043e \u0432\u0438\u0434\u0435\u043e\u0433\u043e\u043e\u0440 \u04af\u0437\u044d\u0433\u0447\u0434\u044d\u044d \u0442\u0430\u0442. \u0414\u0430\u043d\u0441 \u0431\u0430\u0442\u0430\u043b\u0433\u0430\u0430\u0436\u0443\u0443\u043b\u0430\u0430\u0434, \u043e\u043b\u043e\u043d \u043d\u0438\u0439\u0442\u0438\u0439\u043d \u0445\u0438\u0447\u044d\u044d\u043b, \u044d\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0432 \u043a\u043e\u043d\u0442\u0435\u043d\u0442, \u0442\u04e9\u043b\u04e9\u0432\u043b\u04e9\u0433\u0434\u0441\u04e9\u043d \u0434\u0443\u0443\u0434\u043b\u0430\u0433\u0430 \u0442\u0443\u0442\u0430\u043c\u0434 5\u2013100 \u0434\u043e\u043b\u043b\u0430\u0440\u044b\u043d \u0441\u0430\u0440 \u0431\u04af\u0440\u0438\u0439\u043d \u0437\u0430\u0445\u0438\u0430\u043b\u0433\u0430\u0442 \u0442\u04e9\u043b\u0431\u04e9\u0440 \u0442\u043e\u0433\u0442\u043e\u043e\u0433\u043e\u043e\u0440\u043e\u0439."},
gd5(){return"\u0422\u04e9\u043b\u04e9\u0432\u043b\u04e9\u0433\u0434\u0441\u04e9\u043d \u0434\u0443\u0443\u0434\u043b\u0430\u0433\u0430\u0430\u0440 \u0437\u0430\u0430. \u0411\u04af\u043b\u044d\u0433 \u044d\u0441\u0432\u044d\u043b \u0433\u0430\u043d\u0446\u0430\u0430\u0440\u0447\u0438\u043b\u0441\u0430\u043d \u0445\u0438\u0447\u044d\u044d\u043b \u0441\u0430\u043d\u0430\u043b \u0431\u043e\u043b\u0433\u043e\u0436, \u0434\u0443\u0443\u0434\u043b\u0430\u0433\u0430 \u0431\u04af\u0440\u0442 5\u2013100 \u0434\u043e\u043b\u043b\u0430\u0440 \u0430\u0432\u043d\u0430."},
gd6(){return"\u041a\u0443\u0440\u0441\u0443\u0443\u0434\u0430\u0430\u0440 20\u2013500 \u0434\u043e\u043b\u043b\u0430\u0440\u044b\u043d \u04af\u043d\u044d \u0442\u043e\u0433\u0442\u043e\u043e\u0436 \u043c\u04e9\u043d\u0433\u04e9 \u043e\u043b. \u0425\u0438\u0447\u044d\u044d\u043b, \u04af\u0439\u043b \u0430\u0436\u0438\u043b\u043b\u0430\u0433\u0430\u0430, \u04af\u043d\u044d\u043b\u0433\u044d\u044d\u043d\u0438\u0439 \u0431\u04af\u0440\u044d\u043b\u0434\u044d\u0445\u04af\u04af\u043d\u044d\u044d\u0440 \u0434\u0430\u043c\u0436\u0443\u0443\u043b\u0430\u043d \u0445\u0438\u0447\u044d\u044d\u043b\u043b\u044d\u0445 \u0431\u04e9\u0433\u04e9\u04e9\u0434, \u0442\u04e9\u0433\u0441\u0433\u04e9\u043b\u0434 \u043d\u044c \u0433\u044d\u0440\u0447\u0438\u043b\u0433\u044d\u044d\u0433 \u04e9\u0433\u043d\u04e9."},
gd7(){return"\u0421\u043e\u043d\u0438\u0440\u0445\u043e\u043b\u0442\u043e\u0439 \u0445\u0438\u0447\u044d\u044d\u043b\u04af\u04af\u0434 \u0431\u04af\u0442\u044d\u044d\u2014\u04af\u0440\u0433\u044d\u043b\u0442\u0442\u044d\u0439 \u0442\u0430\u043d\u0438\u043b\u0446\u0443\u0443\u043b\u0433\u0430, \u043f\u043e\u0434\u043a\u0430\u0441\u0442, \u043c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u0438\u0430 \u0442\u04af\u04af\u0445 \u044d\u0441\u0432\u044d\u043b \u0431\u0430\u0440\u0438\u043c\u0442\u044b\u0433 \u0430\u0448\u0438\u0433\u043b\u0430. \u0414\u0443\u0443, \u0432\u0438\u0434\u0435\u043e, \u0433\u0440\u0430\u0444\u0438\u043a, \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u043a \u0442\u043e\u043c\u044a\u0451\u043e \u0431\u04af\u0445\u0438\u0439 \u043e\u043b\u043e\u043d \u0430\u0441\u0443\u0443\u043b\u0442\u044b\u0433 \u043d\u044d\u043c. 1\u201350 \u0434\u043e\u043b\u043b\u0430\u0440\u044b\u043d \u0437\u04e9\u0432\u043b\u04e9\u0433\u04e9\u04e9 \u0445\u04af\u043b\u044d\u044d\u043d \u0430\u0432."},
gd8(){return"\u041e\u043b\u043e\u043d \u0442\u0430\u043b\u0442 \u043d\u0438\u0439\u0433\u044d\u043c\u0442\u044d\u0439 \u0445\u043e\u043b\u0431\u043e\u0433\u0434\u043e\u043d \u0448\u0438\u043d\u044d \u0445\u04af\u043c\u04af\u04af\u0441\u0442\u044d\u0439 \u0442\u0430\u043d\u0438\u043b\u0446, \u0445\u044d\u043b \u0434\u0430\u0441\u0433\u0430\u043b \u0445\u0438\u0439, \u043a\u0443\u0440\u0441 \u0437\u0430\u0440, \u044d\u0441\u0432\u044d\u043b \u0437\u04af\u0433\u044d\u044d\u0440 \u0447\u0430\u0442\u043b\u0430\u0436 \u0442\u04e9\u043b\u04e9\u0432\u043b\u04e9\u0433\u0434\u0441\u04e9\u043d \u0434\u0443\u0443\u0434\u043b\u0430\u0433\u0430\u0430\u0440 \u0437\u0430\u0430."},
gd9(){return"AI \u0430\u0448\u0438\u0433\u043b\u0430\u043d \u0445\u044d\u043b\u0434\u044d\u044d \u0434\u0430\u0441\u0433\u0430\u043b \u0445\u0438\u0439\u0436 \u043e\u0439\u043b\u0433\u043e\u043b\u0442\u043e\u043e \u0441\u0430\u0439\u0436\u0440\u0443\u0443\u043b. \u0417\u0443\u0440\u0433\u0430\u0430\u043d \u0445\u044d\u043b\u043d\u0438\u0439 \u0441\u043e\u043d\u0433\u043e\u043b\u0442\u0442\u043e\u0439."},
gda(){return"\u0421\u043e\u043d\u0438\u0440\u0445\u043e\u043b\u0442\u043e\u0439 \u0442\u04af\u04af\u0445 \u0445\u0443\u0432\u0430\u0430\u043b\u0446\u0430\u0430\u0434, \u0430\u043c\u0436\u0438\u043b\u0442, \u0430\u0445\u0438\u0446 \u0433\u0430\u0440\u0433\u0430\u043b\u0442\u0430\u0430 \u0445\u0430\u0440\u0443\u0443\u043b\u0436, \u0448\u0438\u043d\u044d \u0445\u043e\u043b\u0431\u043e\u043e \u0431\u0438\u0439 \u0431\u043e\u043b\u0433\u043e. \u0418\u043d\u0433\u044d\u0441\u043d\u044d\u044d\u0440 \u04af\u0437\u044d\u0433\u0447 \u043d\u044d\u043c\u044d\u0433\u0434\u044d\u043d\u044d."},
gdc(){return"\u042d\u043d\u044d \u04af\u0439\u043b\u0434\u043b\u0438\u0439\u0433 \u043c\u044d\u0440\u0433\u044d\u0436\u043b\u0438\u0439\u043d \u0442\u04af\u0432\u0448\u0438\u043d\u0434 \u04af\u0440\u0433\u044d\u043b\u0436\u043b\u04af\u04af\u043b\u0436 \u043e\u0440\u043b\u043e\u0433\u043e\u043e \u043e\u043b\u043e\u043d \u044d\u0445 \u04af\u04af\u0441\u0432\u044d\u0440\u0442\u044d\u0439 \u0431\u043e\u043b\u0433\u043e\u0445 \u0431\u043e\u043b\u043e\u043c\u0436\u0442\u043e\u0439. \u042d\u043d\u044d \u043d\u044c \u043d\u044d\u043c\u044d\u043b\u0442 \u0430\u0436\u0438\u043b \u044d\u0441\u0432\u044d\u043b \u0431\u04af\u0440\u044d\u043d \u0446\u0430\u0433\u0438\u0439\u043d \u0430\u0436\u0438\u043b \u0431\u0430\u0439\u0436 \u0431\u043e\u043b\u043d\u043e."},
gdd(){return"\u04e8\u043d\u0434\u04e9\u0440 \u04af\u043d\u044d\u0442 LMS \u0441\u0438\u0441\u0442\u0435\u043c\u0434 \u043c\u04e9\u043d\u0433\u04e9 \u0442\u04e9\u043b\u04e9\u0445 \u0448\u0430\u0430\u0440\u0434\u043b\u0430\u0433\u0430\u0433\u04af\u0439. \u042d\u043d\u0434 \u0442\u0430 \u0447\u0430\u043d\u0430\u0440\u0442\u0430\u0439 \u043a\u0443\u0440\u0441 \u0431\u04af\u0442\u044d\u044d\u0436, \u043e\u044e\u0443\u0442\u043d\u044b \u0442\u0430\u0432 \u0442\u0443\u0445, \u0447\u0430\u043d\u0430\u0440\u0442 \u0437\u04e9\u0440\u0447\u0438\u043b\u0433\u04af\u0439 \u0430\u0436\u0438\u043b\u043b\u0430\u0445 \u0431\u043e\u043b\u043e\u043c\u0436\u0442\u043e\u0439."},
gd4(){return"Edhomy \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c \u0430\u0448\u0438\u0433\u043b\u0430\u043d \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433 \u0445\u0438\u0439\u0436, \u0445\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447 \u0442\u0430\u0442\u0430\u0436, \u0441\u0430\u043d\u0430\u043b\u0443\u0443\u0434\u0430\u0430 \u043c\u043e\u043d\u0435\u0442\u0438\u0437\u0430\u0446\u0438 \u0445\u0438\u0439\u0436 \u043c\u044d\u0440\u0433\u044d\u0436\u043b\u0438\u0439\u043d \u043e\u0440\u043b\u043e\u0433\u043e\u043e \u043d\u044d\u043c\u044d\u0433\u0434\u04af\u04af\u043b."},
geE(){return"\u0425\u044d\u0440\u044d\u0432 \u043c\u0430\u043d\u0430\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438 \u0442\u0430\u043b\u0430\u0430\u0440 \u0430\u0441\u0443\u0443\u0445 \u0437\u04af\u0439\u043b \u0431\u0430\u0439\u0432\u0430\u043b \u0434\u043e\u043e\u0440\u0445 \u043c\u0430\u044f\u0433\u0442\u0430\u0430\u0440 \u0431\u0438\u0434\u044d\u043d\u0442\u044d\u0439 \u0445\u043e\u043b\u0431\u043e\u0433\u0434\u043e\u043d\u043e \u0443\u0443."},
