gbe(a){return"\u0410\u043b\u0434\u0430\u0430. \u0414\u0430\u0445\u0438\u043d \u043e\u0440\u043e\u043b\u0434\u043e\u043d\u043e \u0443\u0443"},
gec(){return"\u0418\u043b\u0433\u044d\u044d\u0445\u044d\u044d\u0441 \u04e9\u043c\u043d\u04e9 \u0431\u04af\u0445 \u0442\u0430\u043b\u0431\u0430\u0440\u044b\u0433 \u0431\u04e9\u0433\u043b\u04e9\u043d\u04e9 \u04af\u04af"},
ge8(){return"\u0422\u0430 Edhomy \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439\u043d \u0430\u0436\u0438\u043b\u0442\u0430\u043d \u0431\u043e\u043b \u043d\u044d\u0432\u0442\u0440\u044d\u043d \u043e\u0440\u043d\u043e \u0443\u0443"},
geR(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447\u0438\u0439\u043d \u043d\u044d\u0440, \u043d\u0443\u0443\u0446 \u04af\u0433"},
