gdf(){return"\u0420\u0430\u0441\u0448\u0438\u0440\u044c\u0442\u0435 \u0431\u0438\u0437\u043d\u0435\u0441-\u043c\u043e\u0434\u0435\u043b\u044c"},
gd3(){return"\u041f\u0440\u0438\u0432\u043b\u0435\u043a\u0430\u0439\u0442\u0435 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0438\u044e \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u043c\u0438 \u0432\u0438\u0434\u0435\u043e. \u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0438 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435 \u0435\u0436\u0435\u043c\u0435\u0441\u044f\u0447\u043d\u0443\u044e \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0443 \u043e\u0442 5 \u0434\u043e 100 \u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432 \u043d\u0430 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u0443\u0440\u043e\u043a\u0438, \u044d\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u0438\u043b\u0438 \u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0437\u0432\u043e\u043d\u043a\u0438."},
gd5(){return"\u041f\u0440\u0435\u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0437\u0432\u043e\u043d\u043a\u0438. \u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0439\u0442\u0435 \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u044b\u0435 \u0438\u043b\u0438 \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u043d\u044f\u0442\u0438\u044f, \u0432\u0437\u0438\u043c\u0430\u044f \u043e\u0442 5 \u0434\u043e 100 \u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432 \u0437\u0430 \u0437\u0432\u043e\u043d\u043e\u043a."},
gd6(){return"\u041c\u043e\u043d\u0435\u0442\u0438\u0437\u0438\u0440\u0443\u0439\u0442\u0435 \u043a\u0443\u0440\u0441\u044b \u0441 \u0446\u0435\u043d\u0430\u043c\u0438 \u043e\u0442 20 \u0434\u043e 500 \u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432. \u0414\u0435\u043b\u0438\u0442\u0435\u0441\u044c \u0441\u0432\u043e\u0435\u0439 \u0441\u0442\u0440\u0430\u0441\u0442\u044c\u044e \u0447\u0435\u0440\u0435\u0437 \u0443\u0440\u043e\u043a\u0438, \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438 \u0438 \u043e\u0446\u0435\u043d\u043a\u0438, \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u044f \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f."},
gd7(){return"\u0421\u043e\u0437\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0435 \u0443\u0440\u043e\u043a\u0438 \u0441 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043d\u044b\u043c\u0438 \u0432\u0432\u043e\u0434\u043d\u044b\u043c\u0438, \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0430\u043c\u0438, \u043c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u0438\u0439\u043d\u044b\u043c\u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u044f\u043c\u0438 \u0438\u043b\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043c\u0438. \u0412\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0441 \u0430\u0443\u0434\u0438\u043e, \u0432\u0438\u0434\u0435\u043e, \u0433\u0440\u0430\u0444\u0438\u043a\u0430\u043c\u0438 \u0438 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c\u0438 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f\u043c\u0438. \u041f\u043e\u043b\u0443\u0447\u0430\u0439\u0442\u0435 \u0447\u0430\u0435\u0432\u044b\u0435 \u043e\u0442 1 \u0434\u043e 50 \u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432."},
gd8(){return"\u041e\u0431\u0449\u0430\u0439\u0442\u0435\u0441\u044c \u0441 \u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043d\u044b\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e\u043c, \u0437\u043d\u0430\u043a\u043e\u043c\u044c\u0442\u0435\u0441\u044c \u0441 \u043d\u043e\u0432\u044b\u043c\u0438 \u043b\u044e\u0434\u044c\u043c\u0438, \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0439\u0442\u0435 \u044f\u0437\u044b\u043a\u0438, \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043a\u0443\u0440\u0441\u044b \u0438\u043b\u0438 \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0431\u0449\u0430\u0439\u0442\u0435\u0441\u044c \u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u0437\u0432\u043e\u043d\u043a\u0438 \u0434\u043b\u044f \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f."},
gd9(){return"\u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0439\u0442\u0435 \u044f\u0437\u044b\u043a\u0438 \u0441 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u043e\u043c \u0434\u043b\u044f \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u044f \u043f\u043e\u043d\u0438\u043c\u0430\u043d\u0438\u044f. \u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e \u043d\u0430 \u0448\u0435\u0441\u0442\u0438 \u044f\u0437\u044b\u043a\u0430\u0445."},
gda(){return"\u0420\u0430\u0441\u0448\u0438\u0440\u044f\u0439\u0442\u0435 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0438\u044e, \u0434\u0435\u043b\u044f\u0441\u044c \u0443\u0432\u043b\u0435\u043a\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u044f\u043c\u0438, \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0438\u0440\u0443\u044f \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u0438 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430\u0445\u043e\u0434\u044f \u043d\u043e\u0432\u044b\u0435 \u0437\u043d\u0430\u043a\u043e\u043c\u0441\u0442\u0432\u0430."},
gdc(){return"\u0420\u0430\u0437\u0432\u0438\u0432\u0430\u0439\u0442\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0434\u043e\u0445\u043e\u0434\u0430, \u0437\u0430\u043d\u0438\u043c\u0430\u044f\u0441\u044c \u044d\u0442\u0438\u043c \u043f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u0438\u043b\u0438 \u043f\u043e\u043b\u043d\u043e\u0446\u0435\u043d\u043d\u0430\u044f \u043a\u0430\u0440\u044c\u0435\u0440\u0430 \u0441 \u0432\u044b\u0441\u043e\u043a\u0438\u043c \u0434\u043e\u0445\u043e\u0434\u043e\u043c."},
gdd(){return"\u041d\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u0437\u0430 \u0434\u043e\u0440\u043e\u0433\u0438\u0435 LMS-\u0441\u0438\u0441\u0442\u0435\u043c\u044b. \u0417\u0434\u0435\u0441\u044c \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043a\u0443\u0440\u0441\u044b \u0431\u0435\u0437 \u0443\u0449\u0435\u0440\u0431\u0430 \u0434\u043b\u044f \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u0430 \u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f."},
